import { ParsedNote } from '../types';

/**
 * Parses markdown generated by the AI Notes Generator following the strict 6-point structure:
 * 1. 🏷️ TOPIC TITLE (# ...)
 * 2. 📌 CORE SUMMARY (> *...*)
 * 3. 🔑 KEY TAKEAWAYS (- ...)
 * 4. 📘 DETAILED BREAKDOWN (## ...)
 * 5. ⚠️ CRITICAL CONCEPTS (**concept**)
 * 6. 💡 QUICK MNEMONIC/TIP (> ...)
 */
export function parseStudyNotes(markdown: string): ParsedNote {
  const lines = markdown.split('\n');

  let title = 'Study Notes';
  let coreSummary = '';
  const keyTakeaways: string[] = [];
  const breakdowns: Array<{ heading: string; content: string[] }> = [];
  const criticalConcepts: Array<{ term: string; context?: string }> = [];
  let studyTip = '';

  // Extract all bold words for critical concepts
  const boldRegex = /\*\*([^*]+)\*\*/g;
  const foundConcepts = new Set<string>();
  let match: RegExpExecArray | null;
  while ((match = boldRegex.exec(markdown)) !== null) {
    const raw = match[1].trim();
    // Exclude header labels like "Study Tip:", "Formula:", etc.
    if (
      raw &&
      !raw.toLowerCase().includes('study tip') &&
      !raw.toLowerCase().includes('mnemonic') &&
      !raw.toLowerCase().includes('key takeaway') &&
      !raw.toLowerCase().includes('core summary') &&
      raw.length > 2 &&
      raw.length < 80
    ) {
      if (!foundConcepts.has(raw.toLowerCase())) {
        foundConcepts.add(raw.toLowerCase());
        criticalConcepts.push({ term: raw });
      }
    }
  }

  let currentSection: 'title' | 'summary' | 'takeaways' | 'breakdown' | 'tip' | null = null;
  let currentBreakdownHeading = '';
  let currentBreakdownLines: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // 1. Title (# ...)
    if (line.startsWith('# ') && !line.startsWith('## ')) {
      title = line.replace(/^#\s*/, '').replace(/^[🏷️\s]+/, '').trim();
      continue;
    }

    // 2. Summary detection
    if (
      line.toLowerCase().includes('core summary') ||
      line.includes('📌') ||
      line.includes('SUMMARY')
    ) {
      currentSection = 'summary';
      continue;
    }

    // 3. Takeaways detection
    if (
      line.toLowerCase().includes('key takeaway') ||
      line.includes('🔑') ||
      line.toLowerCase().includes('takeaways')
    ) {
      // Flush previous breakdown if any
      if (currentBreakdownHeading) {
        breakdowns.push({ heading: currentBreakdownHeading, content: [...currentBreakdownLines] });
        currentBreakdownHeading = '';
        currentBreakdownLines = [];
      }
      currentSection = 'takeaways';
      continue;
    }

    // 4. Breakdown detection or Sub-heading (## ...)
    if (
      line.toLowerCase().includes('detailed breakdown') ||
      line.includes('📘')
    ) {
      currentSection = 'breakdown';
      continue;
    }

    // 6. Study Tip detection
    if (
      line.toLowerCase().includes('quick mnemonic') ||
      line.toLowerCase().includes('study tip') ||
      line.includes('💡')
    ) {
      if (currentBreakdownHeading) {
        breakdowns.push({ heading: currentBreakdownHeading, content: [...currentBreakdownLines] });
        currentBreakdownHeading = '';
        currentBreakdownLines = [];
      }
      currentSection = 'tip';
      continue;
    }

    // Section Content Handlers
    if (currentSection === 'summary') {
      if (line.startsWith('>')) {
        const clean = line.replace(/^>\s*/, '').replace(/^\*+|\*+$/g, '').trim();
        if (clean) coreSummary += (coreSummary ? ' ' : '') + clean;
      } else if (line.startsWith('## ') || line.includes('🔑') || line.includes('💡')) {
        // transitioning out
      } else if (line && !line.startsWith('#')) {
        coreSummary += (coreSummary ? ' ' : '') + line.replace(/^\*+|\*+$/g, '');
      }
    } else if (currentSection === 'takeaways') {
      if (line.startsWith('- ') || line.startsWith('* ') || /^\d+\.\s/.test(line)) {
        const clean = line.replace(/^[-*]|\d+\.\s*/, '').trim();
        if (clean) keyTakeaways.push(clean);
      }
    } else if (currentSection === 'breakdown') {
      if (line.startsWith('## ')) {
        if (currentBreakdownHeading) {
          breakdowns.push({ heading: currentBreakdownHeading, content: [...currentBreakdownLines] });
        }
        currentBreakdownHeading = line.replace(/^##\s*/, '').replace(/^[📘\s]+/, '').trim();
        currentBreakdownLines = [];
      } else if (line && !line.startsWith('#') && !line.toLowerCase().includes('study tip')) {
        currentBreakdownLines.push(line);
      }
    } else if (currentSection === 'tip') {
      const clean = line.replace(/^>\s*/, '').replace(/^💡\s*/, '').trim();
      if (clean) {
        studyTip += (studyTip ? '\n' : '') + clean;
      }
    } else {
      // In case no explicit section matched yet, fallback check for Heading 2
      if (line.startsWith('## ') && !line.toLowerCase().includes('breakdown')) {
        if (currentBreakdownHeading) {
          breakdowns.push({ heading: currentBreakdownHeading, content: [...currentBreakdownLines] });
        }
        currentBreakdownHeading = line.replace(/^##\s*/, '').trim();
        currentBreakdownLines = [];
        currentSection = 'breakdown';
      }
    }
  }

  // Final flush of any lingering breakdown
  if (currentBreakdownHeading && currentBreakdownLines.length > 0) {
    breakdowns.push({ heading: currentBreakdownHeading, content: currentBreakdownLines });
  }

  // Fallbacks if formatting was slightly non-standard
  if (!coreSummary && markdown.includes('>')) {
    const blockquoteLines = lines
      .filter((l) => l.startsWith('>'))
      .map((l) => l.replace(/^>\s*/, '').replace(/^\*+|\*+$/g, ''))
      .filter((l) => !l.toLowerCase().includes('study tip'));
    if (blockquoteLines.length > 0) {
      coreSummary = blockquoteLines.slice(0, 3).join(' ');
    }
  }

  if (keyTakeaways.length === 0) {
    // Collect early bullet points
    const bullets = lines
      .filter((l) => l.startsWith('- ') || l.startsWith('* '))
      .slice(0, 4)
      .map((l) => l.replace(/^[-*]\s*/, ''));
    if (bullets.length > 0) {
      keyTakeaways.push(...bullets);
    }
  }

  return {
    title: title || 'Academic Study Notes',
    coreSummary: coreSummary || 'Comprehensive synthesis of the study material highlights.',
    keyTakeaways: keyTakeaways.length > 0 ? keyTakeaways : ['Key conceptual framework synthesized.'],
    breakdowns: breakdowns.length > 0 ? breakdowns : [{ heading: 'Core Analysis', content: lines.slice(10, 25) }],
    criticalConcepts: criticalConcepts.slice(0, 15),
    studyTip: studyTip || 'Review key formulas and relationships using active recall within 24 hours of first reading.',
    rawMarkdown: markdown,
  };
}
